import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/FREQUENCIES.md","filePath":"manual-zh/FREQUENCIES.md","lastUpdated":1785684581000}'),a={name:"manual-zh/FREQUENCIES.md"};function n(r,t,s,E,p,i){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h3 id="_15-2-frequencies" tabindex="-1">15.2 FREQUENCIES <a class="header-anchor" href="#_15-2-frequencies" aria-label="Permalink to &quot;15.2 FREQUENCIES&quot;">​</a></h3><pre><code>FREQUENCIES
        /VARIABLES=var_list
        /FORMAT={TABLE,NOTABLE,LIMIT(limit)}
                {AVALUE,DVALUE,AFREQ,DFREQ}
        /MISSING={EXCLUDE,INCLUDE}
        /STATISTICS={DEFAULT,MEAN,SEMEAN,MEDIAN,MODE,STDDEV,VARIANCE,
                     KURTOSIS,SKEWNESS,RANGE,MINIMUM,MAXIMUM,SUM,
                     SESKEWNESS,SEKURTOSIS,ALL,NONE}
        /NTILES=ntiles
        /PERCENTILES=percent…
        /HISTOGRAM=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                   [{FREQ[(y_max)],PERCENT[(y_max)]}] [{NONORMAL,NORMAL}]
        /PIECHART=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                  [{FREQ,PERCENT}] [{NOMISSING,MISSING}]
        /BARCHART=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                  [{FREQ,PERCENT}]
        /ORDER={ANALYSIS,VARIABLE}


(These options are not currently implemented.)
        /HBAR=…
        /GROUPED=…
</code></pre><p><code>FREQUENCIES</code> 过程为指定变量输出频数表。<code>FREQUENCIES</code> 还可以计算和显示描述性统计量（包括中位数和众数）以及百分位数，还有频数分布的各种图形表示。</p><p><code>VARIABLES</code> 子命令是唯一必需的子命令。指定要分析的变量。</p><p><code>FORMAT</code> 子命令控制输出格式。它有几种可能的设置：</p><ul><li><code>TABLE</code>，默认值，导致为每个指定变量输出频数表。<code>NOTABLE</code> 阻止输出它们。<code>LIMIT</code> 带有数字参数时，会在表中的值数量超过指定数量时阻止输出。</li><li>通常频数表按值升序排序。这是 <code>AVALUE</code>。<code>DVALUE</code> 表按值降序排序。<code>AFREQ</code> 和 <code>DFREQ</code> 表分别按频数升序和降序排序。</li></ul><p><code>MISSING</code> 子命令控制对用户缺失值的处理。当设置 <code>EXCLUDE</code>（默认）时，用户缺失值不包含在频数表或统计量中。当设置 <code>INCLUDE</code> 时，包含用户缺失值。系统缺失值从不包含在统计量中，但列在频数表中。</p><p>可用的 <code>STATISTICS</code> 与 <code>DESCRIPTIVES</code>（见 <a href="./DESCRIPTIVES">DESCRIPTIVES</a>）中可用的相同，另外增加了 <code>MEDIAN</code>（数据的中位数）和 MODE（众数）。（如果有多个众数，则报告最小值。）默认情况下，为每个变量报告均值、均值的标准差、最小值和最大值。</p><p><code>PERCENTILES</code> 导致报告指定的百分位数。百分位数应以 0 到 100（含）之间的数字列表给出。<code>NTILES</code> 子命令导致在数据集划分为指定数量范围的边界处报告百分位数。例如，<code>/NTILES=4</code> 会导致报告四分位数。</p><p><code>HISTOGRAM</code> 子命令导致输出为每个指定数值变量包含直方图。默认情况下 X 轴范围从数据中观察到的最小值到最大值，但 <code>MINIMUM</code> 和 <code>MAXIMUM</code> 关键字可以设置显式范围。直方图不为字符串变量创建。</p><p>指定 <code>NORMAL</code> 可在直方图上叠加正态曲线。</p><p><code>PIECHART</code> 子命令为每个变量向数据添加饼图。每个扇片代表一个值，扇片大小与该值的频数成比例。默认情况下，所有非缺失值都分配扇片。<code>MINIMUM</code> 和 <code>MAXIMUM</code> 关键字可用于将显示的扇片限制为给定值范围。关键字 <code>NOMISSING</code> 导致缺失值从饼图中省略。这是默认设置。如果改为指定 <code>MISSING</code>，则饼图包含一个代表所有系统缺失和用户缺失个案的扇片。</p><p><code>BARCHART</code> 子命令为每个变量生成条形图。<code>MINIMUM</code> 和 <code>MAXIMUM</code> 关键字可用于省略计数超出指定限制的类别。<code>FREQ</code> 选项（默认）使纵坐标显示每个类别的频数，而 <code>PERCENT</code> 选项显示相对百分比。</p><p><code>HISTOGRAM</code> 和 <code>PIECHART</code> 上的 <code>FREQ</code> 和 <code>PERCENT</code> 选项被接受但目前未生效。</p><p><code>ORDER</code> 子命令被接受但被忽略。</p><h4 id="_15-2-1-频数示例" tabindex="-1">15.2.1 频数示例 <a class="header-anchor" href="#_15-2-1-频数示例" aria-label="Permalink to &quot;15.2.1 频数示例&quot;">​</a></h4><p>示例 15.2 对 personnel.sav 文件中的 <strong>sex</strong> 和 <strong>occupation</strong> 变量运行频数分析。这有助于大致了解这些名义变量的分布方式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;personnel.sav&#39;.  frequencies /variables = sex occupation             /statistics = none.</span></span></code></pre></div><p><strong>示例 15.2：</strong> 对 <strong>sex</strong> 和 <strong>occupation</strong> 变量运行频数分析</p><p>如果您使用图形用户界面，对话框默认设置为计算若干统计量。其中一些对分类变量特别无用，因此您可能希望禁用它们。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.2：</strong> 已选择 <strong>sex</strong> 和 <strong>occupation</strong> 变量的频数对话框</p><p>从结果 15.2 可以明显看出，有 33 名男性、21 名女性和 2 名未输入性别的人。</p><p>还可以看到数据中每个职业的数量。处理用作名义值的字符串变量时，运行频数分析有助于检测数据录入条目。请注意，有一个 <strong>occupation</strong> 值被误输入为“Scrientist”。在使用数据之前，应更正此条目或标记为缺失。</p><table tabindex="0"><thead><tr><th></th><th></th><th>频数</th><th>百分比</th><th>有效百分比</th><th>累积百分比</th></tr></thead><tbody><tr><td>有效</td><td>男性</td><td>33</td><td>58.9%</td><td>61.1%</td><td>61.1%</td></tr><tr><td>女性</td><td>21</td><td>37.5%</td><td>38.9%</td><td>100.0%</td><td></td></tr><tr><td>缺失</td><td>.</td><td>2</td><td>3.6%</td><td></td><td></td></tr><tr><td>总计</td><td>56</td><td>100.0%</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>频数</td><td>百分比</td><td>有效百分比</td><td>累积百分比</td></tr><tr><td>有效</td><td>艺术家</td><td>8</td><td>14.3%</td><td>14.3%</td><td>14.3%</td></tr><tr><td>面包师</td><td>2</td><td>3.6%</td><td>3.6%</td><td>17.9%</td><td></td></tr><tr><td>律师</td><td>1</td><td>1.8%</td><td>1.8%</td><td>19.6%</td><td></td></tr><tr><td>木匠</td><td>4</td><td>7.1%</td><td>7.1%</td><td>26.8%</td><td></td></tr><tr><td>清洁工</td><td>4</td><td>7.1%</td><td>7.1%</td><td>33.9%</td><td></td></tr><tr><td>厨师</td><td>7</td><td>12.5%</td><td>12.5%</td><td>46.4%</td><td></td></tr><tr><td>经理</td><td>8</td><td>14.3%</td><td>14.3%</td><td>60.7%</td><td></td></tr><tr><td>数学家</td><td>4</td><td>7.1%</td><td>7.1%</td><td>67.9%</td><td></td></tr><tr><td>画家</td><td>2</td><td>3.6%</td><td>3.6%</td><td>71.4%</td><td></td></tr><tr><td>有效载荷专家</td><td>1</td><td>1.8%</td><td>1.8%</td><td>73.2%</td><td></td></tr><tr><td>水管工</td><td>5</td><td>8.9%</td><td>8.9%</td><td>82.1%</td><td></td></tr><tr><td>科学家</td><td>7</td><td>12.5%</td><td>12.5%</td><td>94.6%</td><td></td></tr><tr><td>Scrientist</td><td>1</td><td>1.8%</td><td>1.8%</td><td>96.4%</td><td></td></tr><tr><td>裁缝</td><td>2</td><td>3.6%</td><td>3.6%</td><td>100.0%</td><td></td></tr><tr><td>总计</td><td>56</td><td>100.0%</td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 15.2：</strong> <strong>sex</strong> 和 <strong>occupation</strong> 的相对频数</p><h4 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to &quot;脚注&quot;">​</a></h4><h5 id="_6" tabindex="-1">(6) <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;(6)&quot;">​</a></h5><p>分箱数根据 Freedman-Diaconis 规则选择：<em>2 \\times IQR(x)n^{-1/3}</em>，其中 <em>IQR(x)</em> 是 <em>x</em> 的四分位距，<em>n</em> 是样本数。注意 <code>EXAMINE</code> 使用不同的算法确定分箱大小。</p>`,29)])])}const l=d(a,[["render",n]]);export{S as __pageData,l as default};
